// === Tab: mySketch.js ===
let img;
let particles = [];
let resolution = 3;
let magnetRadius = 70;
let forceStrength = 3.5;
let friction = 0.92;
let returnSpeed = 0.04;
let maxSpeed = 8;

function preload() {
  img = loadImage('https://openprocessing.org/sketch/2874359/files/THE-BOLD-FANTASTIC-COVER.jpg');
}

function setup() {
  createCanvas(windowWidth, windowHeight);
  initParticles();
  noStroke();
}

function initParticles() {
  particles = [];
  if (!img || img.width === 0) return;

  let imgRatio = img.width / img.height;
  let drawW, drawH;

  if (windowWidth / windowHeight > imgRatio) {
    drawH = windowHeight;
    drawW = windowHeight * imgRatio;
  } else {
    drawW = windowWidth;
    drawH = windowWidth / imgRatio;
  }

  let imgCopy = img.get();
  imgCopy.resize(floor(drawW), floor(drawH));
  imgCopy.loadPixels();

  let offsetX = (windowWidth - drawW) / 2;
  let offsetY = (windowHeight - drawH) / 2;

  for (let x = 0; x < imgCopy.width; x += resolution) {
    for (let y = 0; y < imgCopy.height; y += resolution) {
      let i = (floor(x) + floor(y) * imgCopy.width) * 4;
      let r = imgCopy.pixels[i];
      let g = imgCopy.pixels[i + 1];
      let b = imgCopy.pixels[i + 2];
      let a = imgCopy.pixels[i + 3];
      if (a > 10 && r + g + b > 10) {
        particles.push(new Particle(x + offsetX, y + offsetY, color(r, g, b)));
      }
    }
  }
}

let prevMouseX = 0;
let prevMouseY = 0;
let mouseVelX = 0;
let mouseVelY = 0;

function draw() {
  mouseVelX = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - prevMouseX;
  mouseVelY = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - prevMouseY;
  prevMouseX = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)));
  prevMouseY = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)));

  background(10);
  for (let p of particles) {
    p.update();
    p.display();
  }
}

class Particle {
  constructor(x, y, col) {
    this.home = createVector(x, y);
    this.pos = createVector(x + random(-40, 40), y + random(-40, 40));
    this.vel = createVector(0, 0);
    this.col = col;
    this.settled = false;
  }

  update() {
    // If fully settled, skip all physics — locked in place, zero cost
    if (this.settled) return;

    let dx = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - this.pos.x;
    let dy = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - this.pos.y;
    let mouseDist = sqrt(dx * dx + dy * dy);

    if (mouseDist < magnetRadius && mouseDist > 0) {
      this.settled = false; // Cursor nearby — wake it up
      let falloff = 1 - (mouseDist / magnetRadius);
      falloff = falloff * falloff;

      let pull = (forceStrength * falloff) / mouseDist;
      this.vel.x += dx * pull;
      this.vel.y += dy * pull;

      this.vel.x += mouseVelX * falloff * 0.35;
      this.vel.y += mouseVelY * falloff * 0.35;
    }

    // Spring home
    let hx = this.home.x - this.pos.x;
    let hy = this.home.y - this.pos.y;
    this.vel.x += hx * returnSpeed;
    this.vel.y += hy * returnSpeed;

    this.vel.x *= friction;
    this.vel.y *= friction;

    // Speed cap
    let speed = sqrt(this.vel.x * this.vel.x + this.vel.y * this.vel.y);
    if (speed > maxSpeed) {
      this.vel.x = (this.vel.x / speed) * maxSpeed;
      this.vel.y = (this.vel.y / speed) * maxSpeed;
    }

    this.pos.x += this.vel.x;
    this.pos.y += this.vel.y;

    // SNAP TO HOME: if close enough AND nearly stopped, lock it perfectly
    // This eliminates the micro-jitter pulsing at rest
    let distHome = sqrt(hx * hx + hy * hy);
    if (distHome < 0.4 && speed < 0.3) {
      this.pos.x = this.home.x;
      this.pos.y = this.home.y;
      this.vel.x = 0;
      this.vel.y = 0;
      this.settled = true; // Frozen until cursor wakes it
    }
  }

  display() {
    fill(this.col);
    // resolution+0.5 overlap = zero gaps at rest, seamless photo
    // The 0.5px bleed closes the grid spacing without blurring
    rect(this.pos.x, this.pos.y, resolution + 0.5, resolution + 0.5);
  }
}

// Wake ALL particles when cursor moves — so fluid effect reaches settled ones
function mouseMoved() {
  for (let p of particles) {
    var dx = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - p.home.x;
    var dy = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - p.home.y;
    if (sqrt(dx * dx + dy * dy) < magnetRadius) {
      p.settled = false;
    }
  }
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
  initParticles();
}

